<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    (</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">void</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)tex;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> // use the texture in your UI or pipeline</span></span>
